steps = [
    step("Accept 头解析(服务端提供 application/json、text/html、text/csv,用 best_match):*/*(curl 默认)→ application/json(同等条件取服务器列表里排在前面的);Accept: application/json → JSON;text/html → HTML;Chrome 的导航请求 text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8 → text/html;application/json, text/html 与 text/html, application/json 都 → JSON(q 值相同时看服务器自己的顺序,与客户端写的顺序无关);application/json;q=0.5, text/html;q=0.9 → text/html;text/* → text/html;image/png → 406;application/json;q=0 → 406(q=0 表示不接受);text/html;q=0, */*;q=0.1 → JSON;没有 Accept 头与 garbage → 都是 406。", t=tl(S(1)), done=lidx(S(1), '*/*  ', 'application/json   ', 'text/html   ', 'Chrome'), mark=lidx(S(1), 'image/png', 'q=0 表示不接受', '没有 Accept 头', 'garbage'), kv=KV([['同 q 值', '服务器列表里靠前的赢'], ['q=0', '表示不接受'], ['没有 Accept 头', 'best_match 为 None → 406(本篇的写法)']], ['没有 Accept 头'])),
    step("request.accept_mimetypes 的接口(Chrome 的 Accept 下):解析出的值列表是 [('text/html', 1), ('application/xhtml+xml', 1), ('application/xml', 0.9), ('*/*', 0.8)];best = text/html;accept_html 与 accept_json 都是 True(因为 */* 接受一切);quality('application/json') = 0.8(来自 */*);'application/json' in accept_mimetypes 为 True。所以用 accept_json 判断「客户端想要 JSON」会被 */* 误判,要用 best_match 比较。", t=tl(S(2)), done=lidx(S(2), 'accept_html', 'quality_json'), kv=KV([['best', 'text/html'], ['accept_json', 'True(被 */* 带出来的)'], ['quality(json)', '0.8']], ['accept_json'])),
    step("406 Not Acceptable:Accept: image/png 时返回 406 与 JSON 说明({'error': 'not acceptable', 'offered': […]});所有这类按 Accept 变化的响应都应加 Vary: Accept(本例里 200 与 406 都有),否则缓存可能把 JSON 响应给浏览器。", t=tl(S(3)), done=lidx(S(3), 'Accept: image/png', 'Accept: application/json'), kv=KV([['无法满足', '406 + 说明'], ['按 Accept 变化', '必须加 Vary: Accept']], ['按 Accept 变化'])),
    step("Accept-Language:best_match(['zh-CN','zh-TW','en','en-GB','ja'], default='en')。zh-CN,zh;q=0.9,en;q=0.8 → zh-CN;只写 zh → zh-CN(匹配到第一个 zh 开头的);zh-TW → zh-TW;en-US,en;q=0.9 → en(en-US 没有精确提供,退到 en);fr → 默认 en;ja;q=0.5, en;q=0.9 → en;* → zh-CN(取第一个);没有头 → 默认 en。", t=tl(S(4)), done=lidx(S(4), 'zh-CN,zh;q=0.9', 'zh-TW', 'en-US,en'), mark=lidx(S(4), 'fr', '*  ', '(无)'), kv=KV([['zh', '匹配 zh-CN(第一个 zh-*)'], ['en-US', '退到 en'], ['不支持的 fr', '用 default']], ['zh'])),
    step("Accept-Encoding:Flask 不会自动压缩,只提供解析:gzip, deflate, br → gzip q=1、br q=1、identity q=0;gzip;q=0, identity → gzip 0、identity 1;br;q=1.0, gzip;q=0.8, *;q=0.1 → br 1.0、gzip 0.8、identity 0.1(通配符给了没有列出的)。没有这个头时三项全是 0(这里 identity 的默认接受不会被推断)。压缩要靠 Flask-Compress 之类的扩展或前面的 Nginx。", t=tl(S(5)), done=lidx(S(5), 'gzip, deflate, br'), mark=lidx(S(5), '(无)'), kv=KV([['gzip, deflate, br', 'gzip=1、br=1、identity=0'], ['*;q=0.1', '没列出的得 0.1'], ['没有头', '全是 0']], ['没有头'])),
    step(f"用 URL 后缀选择格式:/ext.json → {ex['/ext.json'][0]} {ex['/ext.json'][1]};/ext.html → {ex['/ext.html'][0]} {ex['/ext.html'][1]};/ext.xml → {ex['/ext.xml'][0]}(不支持的格式)。后缀对浏览器直接访问、复制链接与缓存更友好,可以和 Accept 协商同时支持。", t=tl(S(6)), done=lidx(S(6), '/ext.json', '/ext.html'), mark=lidx(S(6), '/ext.xml'), kv=KV([['/ext.json', 'application/json'], ['/ext.html', 'text/html'], ['/ext.xml', '404']], ['/ext.xml'])),
    step("真实客户端的 Accept:curl 默认发 Accept: */*,不发 Accept-Encoding,User-Agent 是 curl/8.7.1;python-requests 默认 Accept: */*、Accept-Encoding: gzip, deflate, zstd。两者都是 */*,所以在 */* 下服务端提供的第一个类型就是它们得到的类型。", t=tl(S(7)), done=lidx(S(7), 'curl 默认', 'requests 默认'), kv=KV([['curl', 'Accept: */*'], ['requests', 'Accept: */* + Accept-Encoding: gzip, deflate, zstd']], ['requests'])),
]
